R.append((7540633,
("Sopa de frijoles con chile y salsa de aguacate", "Una sopa espesa de tomate y frijoles al estilo mexicano, ideal para una cena contundente de invierno.", "6", "311 g",
 ["1 cucharada de aceite de girasol", "1 cebolla grande, picada", "2 dientes de ajo, machacados", "2 chiles rojos, finamente picados", "1 cucharadita de comino molido", "½ cucharadita de canela molida", "2 latas de 400 g de frijoles rojos, escurridos y enjuagados", "1 lata de 400 g de tomates picados", "1.2 L de caldo de verduras", "1 aguacate de 150 g, pelado y finamente picado", "2 tomates, finamente picados", "4 cucharadas de cilantro fresco, picado", "½ cebolla morada pequeña, finamente picada", "½ chile rojo pequeño, en rodajas (opcional)", "pimienta negra recién molida"],
 ["Caliente el aceite de girasol en una olla grande, añada la cebolla, el ajo y los chiles y fría de 2 a 3 minutos, hasta que la cebolla empiece a ablandarse. Agregue las especias y siga friendo 1 minuto más.", "Agregue a la olla el resto de los ingredientes de la sopa, deje que hierva, tape y cocine a fuego lento durante 20 minutos.", "Pase la sopa a un procesador de alimentos o use una batidora de mano y procese hasta que quede suave (puede ser más fácil hacerlo por tandas); regrésela a la olla y caliéntela. Mientras tanto, mezcle todos los ingredientes de la salsa.", "Sirva la sopa con una cucharada de salsa encima."],
 ["Para una sopa más ligera, use frijoles cannellini en lugar de frijoles rojos.", "Si no quiere una salsa muy picante, simplemente omita el chile.", FVH], []),
("شوربة الفاصوليا الحارة مع صلصة الأفوكادو", "شوربة مكسيكية الطابع غنية بالطماطم والفاصوليا، وهي عشاء شتوي مشبع.", "6", "311 غ",
 ["1 ملعقة كبيرة من زيت عباد الشمس", "1 حبة بصل كبيرة، مفرومة", "2 فص ثوم، مهروس", "2 حبة فلفل أحمر حار، مفرومة ناعمًا", "1 ملعقة صغيرة من الكمون المطحون", "½ ملعقة صغيرة من القرفة المطحونة", "2 علبة (400 غ لكل علبة) من الفاصوليا الحمراء، مصفّاة ومشطوفة", "1 علبة (400 غ) من الطماطم المقطعة", "1.2 لتر من مرق الخضار", "1 حبة أفوكادو (150 غ)، مقشرة ومفرومة ناعمًا", "2 حبة طماطم، مفرومة ناعمًا", "4 ملاعق كبيرة من الكزبرة الخضراء الطازجة، مفرومة", "نصف حبة بصل أحمر صغيرة، مفرومة ناعمًا", "نصف حبة فلفل أحمر حار صغيرة، مقطعة إلى شرائح (اختياري)", "فلفل أسود مطحون طازجًا"],
 ["سخّن زيت عباد الشمس في قدر كبير، وأضف البصل والثوم والفلفل الحار وقلّبها لمدة 2-3 دقائق حتى يبدأ البصل في الليونة. أضف التوابل وتابع التقليب لمدة دقيقة إضافية.", "أضف باقي مكونات الشوربة إلى القدر، واتركها تغلي، ثم غطِّها واتركها على نار هادئة لمدة 20 دقيقة.", "انقل الشوربة إلى محضّر الطعام أو استخدم الخلاط اليدوي واخلطها حتى تصبح ناعمة (قد يكون من الأسهل فعل ذلك على دفعات)، ثم أعدها إلى القدر وسخّنها. في هذه الأثناء، اخلط جميع مكونات الصلصة معًا.", "قدّم الشوربة مع ملعقة من الصلصة فوقها."],
 ["للحصول على شوربة أخف، استخدم الفاصوليا البيضاء (كانيليني) بدلًا من الفاصوليا الحمراء.", "إذا كنت لا تريد صلصة حارة جدًا، فاستغنِ ببساطة عن الفلفل الحار.", FVH], [])))
